mapper.select:
SELECT COUNT(*)
FROM GYE_MEMBER
WHERE GROUP_ID = #{groupId}
  AND MEMBER_ID = #{memberId}

SELECT COUNT(*)
FROM GYE_MEMBER
WHERE GROUP_ID = #{groupId}
  AND MEMBER_ID = #{memberId}
  AND (
      STATUS IN ('ACTIVE', 'EXPELLED')
      OR PAYOUT_RECEIVED_YN = 'Y'
  )

SELECT COUNT(*)
FROM JOIN_REQUEST
WHERE GROUP_ID = #{groupId}
  AND MEMBER_ID = #{memberId}
  AND STATUS = 'PENDING'
  AND CREATED_AT > SYSDATE - 7

SELECT COUNT(*) FROM ( SELECT OWNER_ID AS MEMBER_ID FROM GYE_GROUP WHERE GROUP_ID = #{groupId}
UNION
SELECT MEMBER_ID FROM GYE_MEMBER WHERE GROUP_ID = #{groupId} AND STATUS = 'ACTIVE' )

SELECT NAME
FROM MEMBER
WHERE MEMBER_ID = #{memberId}
